//! Authoring SDK for third-party Octra API Gateway plugins.
//!
//! A plugin is a WebAssembly component that implements [`ApiPlugin`] and
//! declares its exported world with [`export_plugin!`]. The canonical ABI lives
//! in `wit/plugin.wit`; this crate provides the friendly Rust surface and the
//! adapter that bridges the generated bindings to it.
//!
//! Bindings are generated by `cargo component` from `wit/plugin.wit` into
//! `src/bindings.rs`; include that module and export the plugin:
//!
//! ```ignore
//! mod bindings;
//!
//! struct MyPlugin { limit: i64 }
//!
//! impl octra_plugin_sdk::ApiPlugin for MyPlugin {
//!     fn configure(config: serde_json::Value) -> Result<Self, octra_plugin_sdk::Error> {
//!         let limit = config["limit"].as_i64().unwrap_or(100);
//!         Ok(Self { limit })
//!     }
//! }
//!
//! octra_plugin_sdk::export_plugin!(MyPlugin, bindings);
//! ```

use std::fmt;
use std::sync::OnceLock;

use serde_json::Value;

pub use serde_json as __serde_json;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LogLevel {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
}

/// An event delivered because the plugin declared a matching subscription.
#[derive(Debug, Clone)]
pub struct Event {
    pub id: String,
    pub topic: String,
    pub source: String,
    pub timestamp: i64,
    pub payload: Value,
}

/// One scheduled job invocation.
#[derive(Debug, Clone)]
pub struct Job {
    pub id: String,
    pub name: String,
    pub scheduled_for: i64,
    pub attempt: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorKind {
    Config,
    Storage,
    Internal,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error {
    kind: ErrorKind,
    message: String,
}

impl Error {
    pub fn config(message: impl Into<String>) -> Self {
        Self {
            kind: ErrorKind::Config,
            message: message.into(),
        }
    }
    pub fn storage(message: impl Into<String>) -> Self {
        Self {
            kind: ErrorKind::Storage,
            message: message.into(),
        }
    }

    pub fn internal(message: impl Into<String>) -> Self {
        Self {
            kind: ErrorKind::Internal,
            message: message.into(),
        }
    }

    pub fn kind(&self) -> ErrorKind {
        self.kind
    }

    pub fn message(&self) -> &str {
        &self.message
    }
}

impl fmt::Display for Error {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.message)
    }
}

impl std::error::Error for Error {}

/// Host services available to a plugin. The adapter generated by
/// [`export_plugin!`] supplies the implementation.
pub trait Host: Send + Sync {
    fn now_unix(&self) -> i64;
    fn instance_id(&self) -> String;
    fn log(&self, level: LogLevel, message: &str);
    fn kv_get(&self, key: &str) -> Result<Option<String>, String>;
    fn kv_put(&self, key: &str, value: &str, ttl_seconds: Option<u32>) -> Result<(), String>;
    fn kv_delete(&self, key: &str) -> Result<bool, String>;
    fn kv_increment(&self, key: &str, delta: i64, ttl_seconds: Option<u32>) -> Result<i64, String>;
    fn entity_get(&self, entity: &str, key_json: &str) -> Result<Option<String>, String>;
    fn entity_upsert(&self, entity: &str, values_json: &str) -> Result<(), String>;
    fn entity_increment(
        &self,
        entity: &str,
        key_json: &str,
        field: &str,
        delta: i64,
        extra_json: Option<&str>,
    ) -> Result<i64, String>;
    fn entity_delete(&self, entity: &str, key_json: &str) -> Result<bool, String>;
    fn entity_query(&self, entity: &str, query_json: &str) -> Result<String, String>;

    fn authenticate(&self, identity: AuthIdentity) -> Result<(), String>;
    fn authenticated(&self) -> bool;
    fn current_auth(&self) -> Option<AuthIdentity>;
}

static HOST: OnceLock<Box<dyn Host>> = OnceLock::new();

/// Installs the host bridge. Called by the generated adapter.
#[doc(hidden)]
pub fn __install_host(host: Box<dyn Host>) {
    let _ = HOST.set(host);
}

fn host() -> &'static dyn Host {
    HOST.get()
        .map(|host| host.as_ref())
        .expect("the plugin host bridge is not installed")
}

/// Logs through the host. Messages are attributed to the current plugin.
pub mod log {
    use super::{LogLevel, host};

    pub fn trace(message: &str) {
        host().log(LogLevel::Trace, message);
    }

    pub fn debug(message: &str) {
        host().log(LogLevel::Debug, message);
    }

    pub fn info(message: &str) {
        host().log(LogLevel::Info, message);
    }

    pub fn warn(message: &str) {
        host().log(LogLevel::Warn, message);
    }

    pub fn error(message: &str) {
        host().log(LogLevel::Error, message);
    }
}

